# Sentinels tagging container and ambiguous-scalar kinds inside value keys.
# They are plain objects, so they can never equal a string, number, or other
# payload value; identity and hash are stable within the process, which is
# all a per-call engine registry needs.
_VKEY_BOOL = object()
_VKEY_FLOAT = object()
_VKEY_LIST = object()
_VKEY_TUPLE = object()
_VKEY_DICT = object()
_VKEY_OTHER = object()


def _vtype_key(value: Any) -> Any:
    """Type-faithful, sortable identity of a dict key (or other hashable).

    Every identity is a tag-first tuple, so identities of differently typed
    keys always order and compare without ``TypeError`` — an integer fact
    key never merges with or mis-sorts against the string with the same
    digits, and a tuple key never merges with anything else.  Used only for
    dict keys, which need a deterministic order; values use
    :func:`_vvalue_key`.
    """
    if isinstance(value, str):
        return ("s", value)
    if isinstance(value, bool):
        return ("b", value)
    if isinstance(value, int):
        return ("i", value)
    if isinstance(value, float):
        return ("f", value)
    if value is None:
        return ("n",)
    if isinstance(value, tuple):
        return ("t", tuple(_vtype_key(item) for item in value))
    return ("o", type(value).__qualname__, repr(value))


def _vvalue_key(value: Any) -> Any:
    """Type-faithful structural identity of a leaf credential value.

    The reuse registry must never merge values whose compact JSON text
    merely *looks* equal while their Python types differ: an integer fact
    or condition key and the string with the same digits, a tuple and the
    list with the same items, ``True`` and ``1``.  This key walks the
    value once and records the real type of every container and key, so
    only values equal in both type and value share an identity; anything
    else falls through to full validation, which rejects it.  Strings and
    ints map to themselves (they cannot collide with any other type's
    identity); containers, bools, floats, and exotica are tagged with
    sentinels that no payload value can equal.  Dict item order is
    normalized away by sorting on the (type-tagged) keys, and every legal
    credential contains only dicts, lists, strings, bools, ints, and
    nulls, for which the key is exact.  This is a structural walk, not a
    serialization: no text or byte form of the value is produced for
    keying.
    """
    if isinstance(value, str):
        return value
    if isinstance(value, dict):
        # Fast path: a string key is its own identity (no other key type
        # maps to a plain string, and plain strings sort unambiguously), so
        # the common all-string-key dict skips the per-key type tagging.
        items = []
        for key, item in value.items():
            if not isinstance(key, str):
                items = None
                break
            items.append((key, _vvalue_key(item)))
        if items is None:
            items = [
                (_vtype_key(key), _vvalue_key(item))
                for key, item in value.items()
            ]
        items.sort()
        return (_VKEY_DICT, tuple(items))
    if isinstance(value, list):
        return (_VKEY_LIST, tuple([_vvalue_key(item) for item in value]))
    if value is None:
        return None
    if isinstance(value, bool):
        return (_VKEY_BOOL, value)
    if isinstance(value, int):
        return value
    if isinstance(value, float):
        return (_VKEY_FLOAT, value)
    if isinstance(value, tuple):
        return (_VKEY_TUPLE, tuple([_vvalue_key(item) for item in value]))
    return (_VKEY_OTHER, type(value).__qualname__, repr(value))


class _CanonicalDict(dict):
    """A plain dict carrying the root of a canonical generator result.

    It behaves exactly like a plain ``dict`` in every respect — it *is* one:
    equality, ordering, iteration, JSON encoding, and ``isinstance`` checks
    are unchanged.  The only addition is a ``__deepcopy__`` that rebuilds
    the independent copy through the canonical compact JSON form, which is
    far cheaper than the generic recursive copier for the very large
    credential trees these functions return.  The copy is again a
    ``_CanonicalDict`` (so repeated copies stay on the fast path) over plain
    dicts and lists, so nothing beyond copying speed is observable, and the
    copy remains fully independent of the original at every level.
    """

    def __deepcopy__(self, memo: dict) -> Any:
        clone = _CanonicalDict(
            json.loads(json.dumps(self, ensure_ascii=False, separators=(",", ":")))
        )
        memo[id(self)] = clone
        return clone


def _emit(canonical_json: str) -> dict[str, Any]:
    """Materialize a canonical JSON document as an independent result tree."""
    return _CanonicalDict(json.loads(canonical_json))


class _VKey:
    """A hash-consed composite value key.

    Composite nodes (bundles, diffs, proofs) key their registries by tuples
    of scalar fields plus their children's keys.  Plain tuples re-hash the
    whole nested structure on every lookup; wrapping the tuple caches the
    hash once, so a repeat occurrence resolves in O(1).  Equality still
    compares the full underlying tuple, so distinct values can never merge.
    """

    __slots__ = ("parts", "_hash")

    def __init__(self, parts: Any) -> None:
        self.parts = parts
        self._hash = hash(parts)

    def __hash__(self) -> int:
        return self._hash

    def __eq__(self, other: Any) -> bool:
        if not isinstance(other, _VKey):
            return NotImplemented
        return self.parts == other.parts


class _VNode:
    __slots__ = (
        "key", "canonical", "json", "sem", "semkey", "dsem", "dsemkey",
        "truth", "complete",
        "root", "root_after", "members", "before_node", "after_node",
        "digest", "stage_parts",
    )

    def __init__(self) -> None:
        self.key: Any = None
        self.canonical: Any = None
        self.json: str = ""
        self.sem: Any = None
        self.semkey: Any = None
        self.dsem: Any = None
        self.dsemkey: Any = None
        self.truth: bool = False
        self.complete: bool = True
        self.root: str = ""
        self.root_after: str = ""
        self.members: list[Any] = []
        self.before_node: Any = None
        self.after_node: Any = None
        self.digest: str = ""
        self.stage_parts: list[str] = []


class _VEngine:
    def __init__(self) -> None:
        self.cred: dict[str, _VNode] = {}
        self.mbundle: dict[Any, _VNode] = {}
        self.mdiff: dict[Any, _VNode] = {}
        self.p0: dict[Any, _VNode] = {}
        self.b0: dict[Any, _VNode] = {}
        self.d0: dict[Any, _VNode] = {}
        self.p1: dict[Any, _VNode] = {}
        self.b1: dict[Any, _VNode] = {}
        self.d1: dict[Any, _VNode] = {}
        self.p2: dict[Any, _VNode] = {}
        self.b2: dict[Any, _VNode] = {}
        self.d2: dict[Any, _VNode] = {}
        # Generated diffs are fully determined by the two side nodes and the
        # derived change entries; memoizing on those avoids rebuilding the
        # whole five-item payload (and its SHA-256) for a repeated pair.
        self.gen: dict[Any, _VNode] = {}
        # Format checks are pure in the input string, so a validated
        # timestamp or hex64 summary is remembered for the life of the
        # engine (one top-level call) instead of being re-checked at every
        # occurrence.
        self.times: dict[str, str] = {}
        self.hexes: dict[str, str] = {}

    def _time(self, value: Any, field: str) -> str:
        if isinstance(value, str):
            cached = self.times.get(value)
            if cached is not None:
                return cached
        checked = _check_time(value, field)
        self.times[checked] = checked
        return checked

    def _hex64(self, value: Any, field: str) -> str:
        if isinstance(value, str):
            cached = self.hexes.get(value)
            if cached is not None:
                return cached
        checked = _check_hex64(value, field)
        self.hexes[checked] = checked
        return checked

    # ------------------------------------------------------------ leaf cred
    def credential(self, value: Any, field: str) -> _VNode:
        if not isinstance(value, dict):
            raise ValueError(f"{field} must be a credential dict")
        # The reuse identity is a type-faithful structural key, not JSON
        # text: it records the real type of every container and key, so a
        # value that merely serializes like an already-seen credential (an
        # integer fact or condition key where the same digits were verified
        # as a string, a tuple where a list is required) never reuses that
        # credential's verified node.  Such a value falls through to full
        # validation, which reports the structural/type violation as
        # ValueError (never a TypeError), so it is never cached; only a
        # genuine type-and-value match resolves to the cached node.
        key = _VKey(("cred", _vvalue_key(value)))
        node = self.cred.get(key)
        if node is not None:
            return node
        content, declared, recomputed, chain_ok, chain_root = (
            _check_verified_matrix_attestation(value, field)
        )
        # The normalized content is a fresh canonical-order dict owned by
        # this call; appending the declared digest yields the canonical
        # report directly, so no defensive copy is needed before encoding.
        sem = _matrix_credential_semantics(content)
        content["digest"] = declared
        cjson = json.dumps(content, ensure_ascii=False, separators=(",", ":"))
        node = _VNode()
        node.key = key
        node.json = cjson
        node.sem = sem
        node.semkey = (
            "cred",
            json.dumps(node.sem, ensure_ascii=False, sort_keys=True,
                       separators=(",", ":")),
        )
        node.truth = bool(
            chain_ok
            and content["policy"]["root"] == chain_root
            and declared == recomputed
        )
        self.cred[key] = node
        return node

    # ------------------------------------------------------- shared members
    def _bundle_members(self, value, field, plural, singular, parse_child):
        if not isinstance(value, dict) or set(value) != {"root", plural}:
            raise ValueError(
                f"{field} must be a dict with exactly the keys root, {plural}"
            )
        root = self._hex64(value["root"], f"{field}.root")
        raw = value[plural]
        if not isinstance(raw, list) or not raw:
            raise ValueError(f"{field}.{plural} must be a non-empty list")
        members: list[tuple[str, _VNode, str, str]] = []
        seen: set[str] = set()
        previous_id: str | None = None
        for index, member in enumerate(raw):
            mf = f"{field}.{plural}[{index}]"
            if not isinstance(member, dict) or set(member) != {
                "id", singular, "previous", "digest"
            }:
                raise ValueError(
                    f"{mf} must be a dict with exactly the keys "
                    f"id, {singular}, previous, digest"
                )
            item_id = _check_non_empty_str(member["id"], f"{mf}.id")
            if item_id in seen:
                raise ValueError(
                    f"{field}.{plural} contains a duplicate id: {item_id!r}"
                )
            if previous_id is not None and item_id <= previous_id:
                raise ValueError(
                    f"{field}.{plural} must be ordered by id in ascending "
                    "Unicode code point order"
                )
            child = parse_child(member[singular], f"{mf}.{singular}")
            prev = self._hex64(member["previous"], f"{mf}.previous")
            dig = self._hex64(member["digest"], f"{mf}.digest")
            members.append((item_id, child, prev, dig))
            seen.add(item_id)
            previous_id = item_id
        return root, members

    def _assemble_bundle(self, tag, registry, key, root, members, plural, genesis):
        singular = "proof" if plural == "proofs" else "report"
        label = b',"proof":' if plural == "proofs" else b',"report":'
        truth = True
        running = genesis
        parts: list[str] = []
        for item_id, child, prev, dig in members:
            # Hash the member payload incrementally from the cached child
            # bytes instead of concatenating a throwaway payload string.
            hasher = hashlib.sha256(running.encode("ascii"))
            hasher.update(b'{"id":')
            hasher.update(_vjs(item_id).encode("utf-8"))
            hasher.update(label)
            hasher.update(child.json.encode("utf-8"))
            hasher.update(b"}")
            recomputed = hasher.hexdigest()
            parts.append(
                '{"id":' + _vjs(item_id)
                + ',"' + singular + '":'
                + child.json
                + ',"previous":' + _vjs(prev)
                + ',"digest":' + _vjs(dig) + "}"
            )
            if not child.truth or prev != running or dig != recomputed:
                truth = False
            running = recomputed
        if root != running:
            truth = False
        node = _VNode()
        node.key = key
        node.root = root
        node.members = members
        node.truth = truth
        node.sem = [(i, n.sem) for i, n, _p, _d in members]
        node.semkey = (
            tag,
            tuple((i, n.semkey) for i, n, _p, _d in members),
        )
        node.json = "".join(
            [
                '{"root":' + _vjs(root) + ',"' + plural + '":[',
                ",".join(parts),
                "]}",
            ]
        )
        node.canonical = None
        registry[key] = node
        return node

    # ------------------------------------------------------------ mbundle
    def matrix_bundle(self, value: Any, field: str) -> _VNode:
        root, members = self._bundle_members(
            value, field, "reports", "report",
            lambda v, f: self.credential(v, f),
        )
        key = _VKey(
            ("mbundle", root, tuple((i, n.key, p, d) for i, n, p, d in members))
        )
        node = self.mbundle.get(key)
        if node is not None:
            return node
        return self._assemble_bundle(
            "mbundle", self.mbundle, key, root, members, "reports",
            _MATRIX_BUNDLE_GENESIS,
        )

    # ------------------------------------------------------------- pbundle
    def proof_bundle(self, level: int, value: Any, field: str) -> _VNode:
        tag = {0: "b0", 1: "b1", 2: "b2"}[level]
        registry = (self.b0, self.b1, self.b2)[level]
        proof_parse = (
            self.evolution_proof, self.chain_proof, self.bundle_evolution_proof
        )[level]
        root, members = self._bundle_members(
            value, field, "proofs", "proof", proof_parse
        )
        key = _VKey(
            (tag, root, tuple((i, n.key, p, d) for i, n, p, d in members))
        )
        node = registry.get(key)
        if node is not None:
            return node
        return self._assemble_bundle(
            tag, registry, key, root, members, "proofs",
            _CHECKPOINT_BUNDLE_GENESIS
        )

    # -------------------------------------------------------------- diffs
    def _diff_changes(self, value, before_members, after_members, field,
                      side_parse, strict):
        if not isinstance(value, list):
            raise ValueError(f"{field} must be a list of change dicts")
        before_by_id = {m[0]: m for m in before_members}
        after_by_id = {m[0]: m for m in after_members}
        entries: list[tuple[str, str, _VNode | None, _VNode | None]] = []
        seen: set[str] = set()
        previous_id: str | None = None
        for index, change in enumerate(value):
            cf = f"{field}[{index}]"
            if not isinstance(change, dict) or set(change) != (
                _CHECKPOINT_BUNDLE_DIFF_CHANGE_KEYS
            ):
                raise ValueError(
                    f"{cf} must be a dict with exactly the keys id, kind, before, after"
                )
            member_id = _check_non_empty_str(change["id"], f"{cf}.id")
            if member_id in seen:
                raise ValueError(f"{field} contains a duplicate change id: {member_id!r}")
            if previous_id is not None and member_id <= previous_id:
                raise ValueError(
                    f"{field} must be ordered by id in ascending Unicode code "
                    "point order"
                )
            kind = change["kind"]
            if kind not in _CHECKPOINT_BUNDLE_DIFF_KINDS:
                raise ValueError(
                    f"{cf}.kind must be 'added', 'removed', or 'changed'"
                )
            bn = (
                None if change["before"] is None
                else side_parse(change["before"], f"{cf}.before")
            )
            an = (
                None if change["after"] is None
                else side_parse(change["after"], f"{cf}.after")
            )
            bm = before_by_id.get(member_id)
            am = after_by_id.get(member_id)
            if kind == "added":
                if bn is not None or an is None:
                    raise ValueError(
                        f"{cf} is 'added' but before/after do not match the contract"
                    )
                if bm is not None or am is None:
                    raise ValueError(
                        f"{cf} id {member_id!r} is not added between the two bundles"
                    )
                if an.semkey != am[1].semkey:
                    raise ValueError(
                        f"{cf}.after does not equal the after bundle member "
                        f"for id {member_id!r}"
                    )
            elif kind == "removed":
                if bn is None or an is not None:
                    raise ValueError(
                        f"{cf} is 'removed' but before/after do not match the contract"
                    )
                if bm is None or am is not None:
                    raise ValueError(
                        f"{cf} id {member_id!r} is not removed between the two bundles"
                    )
                if bn.semkey != bm[1].semkey:
                    raise ValueError(
                        f"{cf}.before does not equal the before bundle member "
                        f"for id {member_id!r}"
                    )
            else:
                if bn is None or an is None:
                    raise ValueError(
                        f"{cf} is 'changed' but before/after do not match the contract"
                    )
                if bm is None or am is None:
                    raise ValueError(
                        f"{cf} id {member_id!r} must exist in both bundles to be 'changed'"
                    )
                if bn.semkey != bm[1].semkey:
                    raise ValueError(
                        f"{cf}.before does not equal the before bundle member "
                        f"for id {member_id!r}"
                    )
                if an.semkey != am[1].semkey:
                    raise ValueError(
                        f"{cf}.after does not equal the after bundle member "
                        f"for id {member_id!r}"
                    )
            entries.append((member_id, kind, bn, an))
            seen.add(member_id)
            previous_id = member_id

        expected = set(before_by_id) ^ set(after_by_id)
        for member_id in sorted(set(before_by_id) & set(after_by_id)):
            if before_by_id[member_id][1].semkey != after_by_id[member_id][1].semkey:
                expected.add(member_id)
        if strict and seen != expected:
            raise ValueError(
                "changes must list exactly the added, removed, and changed "
                "members, with unchanged members omitted"
            )
        return entries, seen == expected

    @staticmethod
    def _diff_five_segments(before_root, after_root, before, after, entries):
        """Segments of the five-item diff payload, for one-join assembly."""
        change_parts = [
            '{"id":' + _vjs(_id)
            + ',"kind":' + _vjs(kind)
            + ',"before":' + ("null" if bn is None else bn.json)
            + ',"after":' + ("null" if an is None else an.json)
            + "}"
            for _id, kind, bn, an in entries
        ]
        return [
            '{"before_root":' + _vjs(before_root)
            + ',"after_root":' + _vjs(after_root)
            + ',"before":',
            before.json,
            ',"after":',
            after.json,
            ',"changes":[',
            ",".join(change_parts),
            "]}",
        ]

    @staticmethod
    def _segments_digest(segments) -> str:
        # Hash the payload incrementally from its segments instead of
        # concatenating (and re-encoding) a throwaway full-size string.
        hasher = hashlib.sha256()
        for segment in segments:
            hasher.update(segment.encode("utf-8"))
        return hasher.hexdigest()

    def _assemble_diff(self, tag, registry, key, before_root, after_root,
                       digest, before, after, entries, segments=None):
        if segments is None:
            segments = self._diff_five_segments(
                before_root, after_root, before, after, entries
            )
        five_digest = self._segments_digest(segments)
        node = _VNode()
        node.key = key
        node.root = before_root
        node.root_after = after_root
        node.digest = digest
        node.before_node = before
        node.after_node = after
        node.members = entries
        node.json = "".join(
            segments[:-1] + ['],"digest":' + _vjs(digest), "}"]
        )
        node.dsem = {
            "before": before.sem,
            "after": after.sem,
            "changes": [
                {
                    "id": _id,
                    "kind": kind,
                    "before": None if bn is None else bn.sem,
                    "after": None if an is None else an.sem,
                }
                for _id, kind, bn, an in entries
            ],
        }
        node.dsemkey = (
            tag,
            before.semkey,
            after.semkey,
            tuple(
                (
                    _id,
                    kind,
                    None if bn is None else bn.semkey,
                    None if an is None else an.semkey,
                )
                for _id, kind, bn, an in entries
            ),
        )
        node.canonical = None
        registry[key] = node
        return node, five_digest

    def _parse_diff(self, tag, registry, value, field, bundle_parse,
                    side_parse, strict):
        if not isinstance(value, dict) or set(value) != set(
            _CHECKPOINT_BUNDLE_DIFF_REPORT_KEYS
        ):
            raise ValueError(
                f"{field} must be a dict with exactly the keys "
                "before_root, after_root, before, after, changes, digest"
            )
        before_root = self._hex64(value["before_root"], f"{field}.before_root")
        after_root = self._hex64(value["after_root"], f"{field}.after_root")
        digest = self._hex64(value["digest"], f"{field}.digest")
        before = bundle_parse(value["before"], f"{field}.before")
        after = bundle_parse(value["after"], f"{field}.after")
        if before.root != before_root:
            raise ValueError(f"{field}.before_root must equal {field}.before.root")
        if after.root != after_root:
            raise ValueError(f"{field}.after_root must equal {field}.after.root")
        entries, complete = self._diff_changes(
            value["changes"], before.members, after.members,
            f"{field}.changes", side_parse, strict,
        )
        key = _VKey(
            (
                tag, before_root, after_root, digest, before.key, after.key,
                tuple(
                    (i, k, None if bn is None else bn.key,
                     None if an is None else an.key)
                    for i, k, bn, an in entries
                ),
            )
        )
        node = registry.get(key)
        if node is not None:
            return node
        node, recomputed = self._assemble_diff(
            tag, registry, key, before_root, after_root, digest,
            before, after, entries,
        )
        sides_ok = all(
            (bn is None or bn.truth) and (an is None or an.truth)
            for _i, _k, bn, an in entries
        )
        node.truth = bool(
            before.truth and after.truth and sides_ok and digest == recomputed
        )
        node.complete = complete
        return node

    def matrix_diff(self, value: Any, field: str) -> _VNode:
        return self._parse_diff(
            "mdiff", self.mdiff, value, field,
            lambda v, f: self.matrix_bundle(v, f),
            lambda v, f: self.credential(v, f),
            strict=True,
        )

    def proof_diff(self, level: int, value: Any, field: str) -> _VNode:
        tag = {0: "d0", 1: "d1", 2: "d2"}[level]
        registry = (self.d0, self.d1, self.d2)[level]
        bundle_parse = (
            (lambda v, f: self.proof_bundle(0, v, f)),
            (lambda v, f: self.proof_bundle(1, v, f)),
            (lambda v, f: self.proof_bundle(2, v, f)),
        )[level]
        side_parse = (
            self.evolution_proof, self.chain_proof, self.bundle_evolution_proof
        )[level]
        return self._parse_diff(
            tag, registry, value, field, bundle_parse, side_parse, strict=False
        )

    def generate_diff(self, level, before: _VNode, after: _VNode) -> _VNode:
        """Canonical diff a generator produces from two canonical bundles."""
        if level == -1:
            tag, registry = "mdiff", self.mdiff
        else:
            tag = {0: "d0", 1: "d1", 2: "d2"}[level]
            registry = (self.d0, self.d1, self.d2)[level]
        before_by_id = {m[0]: m for m in before.members}
        after_by_id = {m[0]: m for m in after.members}
        entries: list[tuple[str, str, _VNode | None, _VNode | None]] = []
        for member_id in sorted(set(before_by_id) | set(after_by_id)):

"""HTTP interface for the regulation policy compiler service."""

from __future__ import annotations

import json
import os
from typing import Any

from fastapi import FastAPI, Request, Response
from fastapi.responses import JSONResponse

from .history import DecisionHistory, verify_audit, verify_audit_bundle
from .policy import (
    _check_fact_map,
    _check_non_empty_str,
    _check_time,
    _validate_rules,
    bundle_evolution_checkpoint,
    bundle_evolution_checkpoint_bundle,
    bundle_evolution_checkpoint_bundle_diff,
    bundle_evolution_checkpoint_bundle_evolution,
    checkpoint_chain,
    checkpoint_chain_checkpoint,
